// BAD: N+1 problem — 1 query for orders + N queries for customers
@Query("SELECT o FROM Order o WHERE o.status = :status")
List<Order> findByStatus(String status);

var orders = orderRepository.findByStatus("SHIPPED"); // 1 query
for (var order : orders) {
    var customerName = order.getCustomer().getName(); // N queries!
    System.out.println(customerName);
}

// GOOD: JOIN FETCH solution — single query with JOIN
@Query("SELECT o FROM Order o JOIN FETCH o.customer WHERE o.status = :status")
List<Order> findByStatusWithCustomer(String status);

var orders = orderRepository.findByStatusWithCustomer("SHIPPED"); // 1 query total
for (var order : orders) {
    var customerName = order.getCustomer().getName(); // no additional query
    System.out.println(customerName);
}

// ALTERNATIVE: @EntityGraph solution
@EntityGraph(attributePaths = {"customer"})
List<Order> findByStatus(String status); // 1 query with LEFT OUTER JOIN

// PROBLEM: accessing lazy association outside transaction
@Service
public class OrderService {
    public Order findOrder(Long id) {
        return orderRepository.findById(id).orElseThrow(); // transaction ends here
    }
}

@RestController
public class OrderController {
    public String getOrderDetails(Long id) {
        var order = orderService.findOrder(id);
        var items = order.getItems(); // LazyInitializationException!
        return items.toString();
    }
}

// FIX 1: Extend transaction scope with @Transactional
@Transactional(readOnly = true)
public String getOrderDetails(Long id) {
    var order = orderService.findOrder(id);
    var items = order.getItems(); // works — still in transaction
    return items.toString();
}

// FIX 2: Load association eagerly in service with JOIN FETCH
@Query("SELECT o FROM Order o JOIN FETCH o.items WHERE o.id = :id")
Optional<Order> findByIdWithItems(Long id);

@Entity
public class Order {
    @Id
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY) // default stays LAZY
    private Customer customer;

    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY)
    private List<OrderItem> items;
}

@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {

    // Load customer eagerly for this query only
    @EntityGraph(attributePaths = {"customer"})
    List<Order> findByStatus(String status);

    // Load both customer and items eagerly
    @EntityGraph(attributePaths = {"customer", "items"})
    Optional<Order> findById(Long id);

    // No @EntityGraph — uses default LAZY behavior
    List<Order> findByCustomerId(Long customerId);
}

// WRONG: JOIN without FETCH — filters but doesn't load association
@Query("SELECT o FROM Order o JOIN o.customer c WHERE c.country = :country")
List<Order> findByCustomerCountry(String country);

var orders = repo.findByCustomerCountry("USA");
for (var order : orders) {
    var name = order.getCustomer().getName(); // still causes lazy load!
}

// CORRECT: JOIN FETCH — loads association in same query
@Query("SELECT o FROM Order o JOIN FETCH o.customer WHERE o.status = :status")
List<Order> findByStatusWithCustomer(String status);

var orders = repo.findByStatusWithCustomer("SHIPPED");
for (var order : orders) {
    var name = order.getCustomer().getName(); // no additional query
}

// Multiple associations: load customer and items together
@Query("SELECT DISTINCT o FROM Order o " +
       "JOIN FETCH o.customer " +
       "JOIN FETCH o.items " +
       "WHERE o.status = :status")
List<Order> findByStatusWithDetails(String status);

@Entity
public class User {
    @Id
    private Long id;

    // GOOD: Keep collections LAZY by default
    @OneToMany(mappedBy = "author", fetch = FetchType.LAZY)
    private List<Post> posts;

    // GOOD: Even single associations can be LAZY if not always needed
    @ManyToOne(fetch = FetchType.LAZY)
    private Department department;
}

@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    // Query 1: Just checking username — no associations needed
    boolean existsByUsername(String username); // fast, no joins

    // Query 2: User profile page — need department
    @EntityGraph(attributePaths = {"department"})
    Optional<User> findByUsername(String username);

    // Query 3: User's post list page — need posts
    @Query("SELECT u FROM User u JOIN FETCH u.posts WHERE u.id = :id")
    Optional<User> findByIdWithPosts(Long id);
}
